"""Play the fixture generated by TestLiveSubstitutePlayback with the site's two decoders."""
import argparse
import functools
import http.server
import json
from pathlib import Path
import shutil
import threading
import time

from selenium import webdriver
from selenium.webdriver.common.by import By

parser = argparse.ArgumentParser()
parser.add_argument("browser", choices=["chrome", "safari"])
parser.add_argument("directory", type=Path)
args = parser.parse_args()
root = args.directory
shutil.copyfile(Path(__file__).with_name("index.html"), root / "index.html")
requested = set()


class MediaHandler(http.server.SimpleHTTPRequestHandler):
    extensions_map = {**http.server.SimpleHTTPRequestHandler.extensions_map,
                      ".m3u8": "application/vnd.apple.mpegurl", ".m4s": "video/mp4"}

    def do_GET(self):
        requested.add(self.path)
        super().do_GET()


handler = functools.partial(MediaHandler, directory=str(root))
with http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler) as server:
    threading.Thread(target=server.serve_forever, daemon=True).start()
    if args.browser == "chrome":
        options = webdriver.ChromeOptions()
        options.add_argument("--headless=new")
        options.add_argument("--autoplay-policy=no-user-gesture-required")
        driver = webdriver.Chrome(options=options)
    else:
        driver = webdriver.Safari()
    try:
        mode = "native" if args.browser == "safari" else "mse"
        driver.get(f"http://127.0.0.1:{server.server_port}/index.html?{mode}")
        driver.find_element(By.TAG_NAME, "button").click()
        deadline = time.monotonic() + 65
        while time.monotonic() < deadline:
            result = driver.execute_script("return window.result")
            if result and (result["errors"] or (result["last"] or 0) > 26):
                break
            time.sleep(0.5)
        print(json.dumps(result, indent=2), flush=True)
        assert result and not result["stalls"] and not result["errors"], "playback stalled or failed"
        assert result["first"] < 1 and result["middle"] > 10 and result["end"] > 10 and result["last"] > 26
        assert {"/480p/seg-000000.m4s", "/480p/sub-seg-000001.m4s", "/480p/seg-000002.m4s"} <= requested
        assert "/480p/seg-000001.m4s" not in requested
    finally:
        driver.quit()
        server.shutdown()
